using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Reflection;using System.Diagnostics;using System.Drawing;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.Windows.Forms;
class SetupForm:Form {TextBox location=new TextBox();Label status=new Label();Button install=new Button();bool completed;CheckBox shortcut=new CheckBox(),launch=new CheckBox();public SetupForm(){Text="오름목 · 데스크톱 앱 설치";Font=new Font("맑은 고딕",10);BackColor=Color.FromArgb(247,246,240);Width=610;Height=420;StartPosition=FormStartPosition.CenterScreen;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;var panel=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(30),ColumnCount=1};Controls.Add(panel);panel.Controls.Add(new Label{Text="오름목  OREUM MOK",AutoSize=true,Font=new Font(Font.FontFamily,23,FontStyle.Bold),ForeColor=Color.FromArgb(28,58,45)});panel.Controls.Add(new Label{Text="Windows 전용 프로그램 설치 · 브라우저 / WebView 미사용\n기존 오름목을 종료한 뒤 설치하세요. 계정·고객 자료는 보존합니다.",AutoSize=true});panel.Controls.Add(new Label{Text="설치 폴더",AutoSize=true});location.Text=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","OreumMokNative");location.Dock=DockStyle.Top;panel.Controls.Add(location);shortcut.Text="바탕화면에 오름목 아이콘 만들기";shortcut.Checked=true;shortcut.AutoSize=true;panel.Controls.Add(shortcut);launch.Text="설치 후 프로그램 실행";launch.Checked=true;launch.AutoSize=true;panel.Controls.Add(launch);status.AutoSize=true;panel.Controls.Add(status);install.Text="설치 / 업그레이드";install.Height=42;install.Dock=DockStyle.Top;install.Click+=(s,e)=>{if(completed){Close();return;}install.Enabled=false;try{NativeInstall.Run(location.Text,shortcut.Checked,launch.Checked);status.Text="설치와 파일 검증을 완료했습니다.";install.Text="닫기";install.Enabled=true;completed=true;}catch(Exception ex){status.Text=ex.Message;install.Enabled=true;}};panel.Controls.Add(install);}}
static class NativeInstall {
static string Hash(string file){using(var h=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(h.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
public static void Run(string folder,bool shortcut,bool launch){string target=Path.GetFullPath(folder),prefix=target.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;foreach(Process p in Process.GetProcessesByName("OreumMok")){try{if(Path.GetFullPath(p.MainModule.FileName)==Path.Combine(target,"OreumMok.exe"))throw new InvalidOperationException("실행 중인 오름목을 닫은 뒤 다시 설치하세요.");}catch(InvalidOperationException){throw;}catch{}}
using(Stream checkStream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var checkZip=new ZipArchive(checkStream,ZipArchiveMode.Read)){foreach(var entry in checkZip.Entries){string file=Path.GetFullPath(Path.Combine(target,entry.FullName));if(!file.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("설치 파일 경로 오류");if(File.Exists(file)){try{using(var handle=File.Open(file,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){} }catch(IOException){throw new IOException("기존 오름목 창을 모두 닫은 뒤 다시 설치하세요. 실행 중인 파일: "+Path.GetFileName(file));}}}}Directory.CreateDirectory(target);string backup=Path.Combine(target,"upgrade-backups",DateTime.Now.ToString("yyyyMMdd-HHmmss"));using(Stream embedded=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var zip=new ZipArchive(embedded,ZipArchiveMode.Read)){foreach(var entry in zip.Entries){string destination=Path.GetFullPath(Path.Combine(target,entry.FullName));if(!destination.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("설치 파일 경로 오류");if(entry.FullName.EndsWith("/")){Directory.CreateDirectory(destination);continue;}Directory.CreateDirectory(Path.GetDirectoryName(destination));if(File.Exists(destination)){Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(backup,entry.FullName)));File.Copy(destination,Path.Combine(backup,entry.FullName),true);}using(var input=entry.Open())using(var output=File.Create(destination))input.CopyTo(output);}}
var json=new JavaScriptSerializer();var hashes=json.Deserialize<System.Collections.Generic.Dictionary<string,string>>(File.ReadAllText(Path.Combine(target,"native-checksums.json")));foreach(var pair in hashes){string f=Path.GetFullPath(Path.Combine(target,pair.Key));if(!f.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)||Hash(f)!=pair.Value)throw new Exception("설치 검증 실패: "+pair.Key);}if(shortcut){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);string desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);dynamic link=shell.CreateShortcut(Path.Combine(desktop,"오름목.lnk"));link.TargetPath=Path.Combine(target,"OreumMok.exe");link.WorkingDirectory=target;link.IconLocation=Path.Combine(target,"oreummok.ico")+",0";link.Description="오름목 네이티브 데스크톱 앱";link.Save();}File.WriteAllText(Path.Combine(target,"installation-result.json"),json.Serialize(new{version="0.24.0",native=true,verified=true,installed=DateTime.Now.ToString("o"),target=target}));if(launch)Process.Start(new ProcessStartInfo(Path.Combine(target,"OreumMok.exe")){WorkingDirectory=target});}
[STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Contains("--silent")){string flag=args.FirstOrDefault(x=>x.StartsWith("--target="));if(flag==null)throw new Exception("Silent installation requires --target.");Run(flag.Substring(9),!args.Contains("--no-shortcut"),!args.Contains("--no-launch"));return 0;}Application.Run(new SetupForm());return 0;}catch(Exception e){if(args.Contains("--silent")){string log=args.FirstOrDefault(x=>x.StartsWith("--log="));if(log!=null)File.WriteAllText(log.Substring(6),e.ToString());return 1;}MessageBox.Show(e.Message,"오름목 설치 오류");return 1;}}
}
